sys_script_client.script:
function onLoad() {
    var connection_details = new GlideAjax("GetConnectionDetails");
    connection_details.addParam("sysparm_name", "getConnectionDetails");
    connection_details.getXML(getResponse);

    function getResponse(response) {
        var res = response.responseXML.documentElement.getAttribute("answer");
        try {
            res = JSON.parse(res);
        } catch (err) {
            alert("Could not load the connection details");
        }
        g_form.setValue("end_point", res["end_point"]);
        g_form.setValue("application_id", res["application_id"]);
        g_form.setValue("application_secret", res["application_secret"]);
        g_form.setValue("mid_server", res["mid_server"]);
		g_form.setValue("key_manager_pin", res["key_manager_pin"]);
    }
}
